//! W3C RDF 1.1 conformance court for the Turtle / N-Triples / N-Quads
//! dialect paths of `graphlaw::dialect`.
//!
//! Corpus: official W3C test suites vendored under `tests/fixtures/w3c/`
//! (see that README for provenance and license). The inventory lives in
//! `tests/w3c_manifest.rs`, generated by `scripts/gen_w3c_manifest.sh`.
//!
//! Court rules:
//! - positive entries must parse via `graphlaw::dialect::parse_rdf`, using
//!   the W3C manifest's `mf:assumedTestBase` as the base IRI;
//! - negative entries must yield a typed `Refusal` (no panic, no Ok);
//! - a negative entry the engine accepts is a REAL DIVERGENCE: it lands in
//!   its own loud bucket, and must be registered in `KNOWN_DIVERGENCES` —
//!   an unregistered divergence fails the court. Closing a divergence in
//!   the engine breaks the literal counts and forces register removal.
//! - per-dialect counts are asserted as literals computed from the
//!   manifest, so a regression or an accidentally-skipped file breaks;
//! - every entry lands in exactly one bucket (passed / refused /
//!   known-diverged) and the receipt totals equal the manifest length.

#[path = "w3c_manifest.rs"]
mod manifest;

use manifest::{Dialect, Kind, ENTRIES};

/// The W3C manifest's `mf:assumedTestBase` per dialect.
fn base_of(d: Dialect) -> Option<&'static str> {
    match d {
        Dialect::Turtle => Some("https://w3c.github.io/rdf-tests/rdf/rdf11/rdf-turtle/"),
        Dialect::NTriples => Some("https://w3c.github.io/rdf-tests/rdf/rdf11/rdf-n-triples/"),
        Dialect::NQuads => Some("https://w3c.github.io/rdf-tests/rdf/rdf11/rdf-n-quads/"),
        Dialect::Trig => Some("https://w3c.github.io/rdf-tests/rdf/rdf11/rdf-trig/"),
        Dialect::RdfXml => Some("https://w3c.github.io/rdf-tests/rdf/rdf11/rdf-xml/"),
    }
}

fn dialect_of(d: Dialect) -> graphlaw::dialect::Dialect {
    match d {
        Dialect::Turtle => graphlaw::dialect::Dialect::Turtle,
        Dialect::NTriples => graphlaw::dialect::Dialect::NTriples,
        Dialect::NQuads => graphlaw::dialect::Dialect::NQuads,
        Dialect::Trig => graphlaw::dialect::Dialect::TriG,
        Dialect::RdfXml => graphlaw::dialect::Dialect::RdfXml,
    }
}

